bash -lc python - <<'PY'
import requests
u='https://gt990datalake-rawdata.s3.amazonaws.com/EfileData/XmlFiles/202501349349105365_public.xml'
try:
 r=requests.get(u,timeout=15)
 print(r.status_code,len(r.content),r.url,r.text[:200]);
 if r.ok: open('/mnt/data/goodventures_990_2024.xml','wb').write(r.content)
except Exception as e:print(repr(e))
PY

bash -lc python - <<'PY'
import requests
u='https://collusion.wiki/explorer/download/full-wiki-logs.zip'
try:
 r=requests.get(u,timeout=15)
 print(r.status_code,len(r.content),r.headers.get('content-type'),r.url)
 if r.status_code==200 and r.content.startswith(b'PK'): open('/mnt/data/collusion-wiki-logs.zip','wb').write(r.content)
except Exception as e: print(type(e).__name__,str(e)[:500])
PY
